INSERT INTO `mount` (`Name`, `SourceText`, `Description`, `ID`, `MountTypeID`, `Flags`, `SourceTypeEnum`, `SourceSpellID`, `PlayerConditionID`, `MountFlyRideHeight`, `UiModelSceneID`, `MountSpecialRiderAnimKitID`, `MountSpecialSpellVisualKitID`, `VerifiedBuild`) VALUES
('Chittering Animite', '|cFFFFD200Adventures:|r Shadowlands|n', 'These exceptionally agile fliers make excellent mounts once they\'ve been trained not to sap every ounce of anima from their rider.', 1309, 248, 128, 0, 312776, 0, 0, 4, 0, 0, 37474),
('Umbral Scythehorn', '|cFFFFD200Vendor: |rSpindlenose|n|cFFFFD200Zone: |rArdenweald|n', 'Umbral gorm are the most docile of all gorm, but they also grow the largest horns and mandibles. They are probably so docile because other creatures avoid riling them.', 1420, 230, 0, 2, 340503, 0, 0, 4, 0, 0, 37474),
('Sinrunner Blanchy', '|cFFFFD200NPC:|r Dead Blanchy |n|cFFFFD200Location:|r Revendreth|n |n', 'In life, Blanchy appeared to be an affectionate, well-behaved horse of excellent disposition and appetite. What evils must she have committed in secret to have earned her place among the condemned souls of Revendreth?', 1414, 230, 0, 0, 339588, 0, 0, 43, 0, 0, 37474),
('Lucky Yun', '|cFFFFD200In Game Shop|r|n', 'The Pandaren believe that merely rubbing one\'s hands on the shiny hide of the ox will grant prosperity, the challenge is catching it.', 1291, 248, 0, 9, 308087, 0, 0, 4, 0, 0, 37474),
('Snowstorm', '|cFFFFD200Blizzard\'s 30th Anniversary|r ', 'He comes from the ice and snow, under the Azeroth sun where adventurers go.', 1424, 230, 0, 7, 341821, 0, 0, 45, 0, 0, 37474);
