(15707, '7.2 OHM Class Mount - DK - IGC - Offsets', 'WaitForTrigger(\"SceneInitialized\")  \n\n-- SHOT 040 ------------------------------------------------------------\n\nfunction playerOffset_040()\n\n	local base = 0.6\n\n	if		(human) 		then	raceScale = 1.5		raceHeight = (base + -0.17)\n	elseif	(dwarf) 		then	raceScale = 1.7		raceHeight = (base + 0.1)\n	elseif	(nightelf) 		then	raceScale = 1.25	raceHeight = (base + -0.17)\n	elseif	(gnome) 		then	raceScale = 2.0		raceHeight = (base + 0.4)	\n	elseif	(draenei_m) 	then	raceScale = 1.2		raceHeight = (base + -0.2)	\n	elseif	(draenei_f)		then	raceScale = 1.25	raceHeight = (base + -0.1)	\n	elseif	(worgen_m) 		then	raceScale = 1.0		raceHeight = (base + 0.3)			\n	elseif	(worgen_f)		then	raceScale = 1.2		raceHeight = (base + 0)			\n	elseif	(raceKultiran)  then	raceScale = 1.2		raceHeight = (base + -0.2)	\n	elseif	(pandaren_m) 	then	raceScale = 1.2		raceHeight = (base + 0)	\n	elseif	(pandaren_f) 	then	raceScale = 1.5		raceHeight = (base + -0.17)\n\n	\n	elseif 	(orc_m) 		then	raceScale = 1.1		raceHeight = (base + 0.3)	\n	elseif 	(orc_f) 		then	raceScale = 1.4		raceHeight = (base + 0)	\n	elseif 	(undead) 		then	raceScale = 1.5		raceHeight = (base + 0)	\n	elseif 	(tauren_m)	 	then	raceScale = 0.73	raceHeight = (base + 0.65)\n	elseif 	(tauren_f)	 	then	raceScale = 1.0		raceHeight = (base + 0.05)\n	elseif 	(troll_m) 		then	raceScale = 1.1		raceHeight = (base + 0.1)	\n	elseif 	(troll_f) 		then	raceScale = 1.2		raceHeight = (base + 0)	\n	elseif 	(bloodelf) 		then	raceScale = 1.5		raceHeight = (base + -0.2)	\n	elseif 	(goblin) 		then	raceScale = 2.0		raceHeight = (base + 0.2)		\n	elseif	(raceZandalari) then	raceScale = 1.0		raceHeight = (base + 0.05)\n	\n	else	print(\"Invalid race\")\n	end	\nend\n\n-- SHOT 060 ----------------------------------------------------------\n\nfunction playerOffset_060()\n\n	local base = 4.8\n	\n	if		(human) 		then	raceScale = 1.5		raceHeight = (base + -0.1)	\n	elseif	(dwarf) 		then	raceScale = 1.7		raceHeight = (base + 0)	\n	elseif	(nightelf) 		then	raceScale = 1.3		raceHeight = (base + -0.3)	\n	elseif	(gnome) 		then	raceScale = 2.0		raceHeight = (base + 0.5)			\n	elseif	(draenei_m) 	then	raceScale = 1.2		raceHeight = (base + -0.1)		\n	elseif	(draenei_f) 	then	raceScale = 1.25	raceHeight = (base + 0)	\n	elseif	(worgen_m) 		then	raceScale = 1.0		raceHeight = (base + 0.4)	\n	elseif	(worgen_f)		then	raceScale = 1.2		raceHeight = (base + 0)	\n	elseif	(raceKultiran)  then	raceScale = 1.2		raceHeight = (base + -0.1)		\n	elseif	(pandaren_m)	then	raceScale = 1.1		raceHeight = (base + -0.1)		\n	elseif	(pandaren_f) 	then	raceScale = 1.5		raceHeight = (base + -0.1)	\n	\n	elseif 	(orc_m) 		then	raceScale = 1.1		raceHeight = (base + 0.3)		\n	elseif 	(orc_f) 		then	raceScale = 1.4		raceHeight = (base + 0)		\n	elseif 	(undead) 		then	raceScale = 1.5		raceHeight = (base + 0)		\n	elseif 	(tauren_m) 		then	raceScale = 0.7		raceHeight = (base + 0.8)	\n	elseif 	(tauren_f) 		then	raceScale = 1.1		raceHeight = (base + -0.1)	\n	elseif 	(troll_m) 		then	raceScale = 1.1		raceHeight = (base + 0.25)	\n	elseif 	(troll_f) 		then	raceScale = 1.2		raceHeight = (base + 0)	\n	elseif 	(bloodelf) 		then	raceScale = 1.5		raceHeight = (base + -0.1)	\n	elseif 	(goblin) 		then	raceScale = 2.0		raceHeight = (base + 0.2)	\n	elseif	(raceZandalari) then	raceScale = 1.2		raceHeight = (base + -0.1)		\n	\n	else	print(\"Invalid race\")\n	end	\nend\n\n-- SHOT 110 ------------------------------------------------------------\n\n-- 137.473\n\nfunction playerOffset_110()\n\n	local base = 51.3\n	\n	if		(human) 		then	raceScale = 1.4		raceHeight = (base + 0.06)\n	elseif	(dwarf) 		then	raceScale = 1.6		raceHeight = (base + 0.4)\n	elseif	(nightelf) 		then	raceScale = 1.2		raceHeight = (base + 0.1)\n	elseif	(gnome) 		then	raceScale = 1.5		raceHeight = (base + 1.17)	\n	elseif	(draenei_m) 	then	raceScale = 1.1		raceHeight = (base + 0.1)\n	elseif	(draenei_f) 	then	raceScale = 1.2		', 37474),
(15146, '7.2 OHM Class Mount - DK - IGC - Functions', 'WaitForTrigger(\"ActorsLoaded\")  \n\n----------------------------------------------------------------------------------\n-- Adjusts heights for difference races\n\n-- Defaults\nraceHeight = 0\nraceScale = 1\n\nfunction raceCheck()\n	if		(human) 		then	raceScale = 1.5		\n	elseif	(dwarf) 		then	raceScale = 1.7		\n	elseif	(nightelf) 		then	raceScale = 1.25	\n	elseif	(gnome) 		then	raceScale = 2		\n	elseif	(draenei_m)		then	raceScale = 1.2		\n	elseif	(draenei_f)		then	raceScale = 1.25	\n	elseif	(worgen_m)		then	raceScale = 1.0		\n	elseif	(worgen_f) 		then	raceScale = 1.2		\n	elseif	(raceKultiran) 	then	raceScale = .85		\n	elseif	(pandaren_f) 	then	raceScale = 1		\n	elseif	(pandaren_m) 	then	raceScale = 1.2		\n	\n	elseif 	(orc_m) 		then	raceScale = 1.1		\n	elseif 	(orc_f) 		then	raceScale = 1.4		\n	elseif 	(undead) 		then	raceScale = 1.5		\n	elseif 	(tauren_m) 		then	raceScale = 0.75	\n	elseif 	(tauren_f) 		then	raceScale = 1.0		\n	elseif 	(troll_m) 		then	raceScale = 1.1		\n	elseif 	(troll_f) 		then	raceScale = 1.2		\n	elseif 	(bloodelf)	 	then	raceScale = 1.5		\n	elseif 	(goblin) 		then	raceScale = 2		\n	elseif 	(raceZandalari) then	raceScale = .85		\n	end	\nend\n\n----------------------------------------------------------------------------------\n-- Checks the player\'s spec and assigns appropriate mount skin.\n\nspecBlood = scene:EvalPlayerCondition( 41732 )\nspecFrost = scene:EvalPlayerCondition( 41733 )\nspecUnholy = scene:EvalPlayerCondition( 41734 )\n\nlocal color = {\n	red = 14771;\n	green = 32562;\n	blue = 6763;\n}\n\nspecColor = color.blue -- in case nothing goes right, pick blue\n\nfunction specCheck ()\n	if 		( specBlood ) then 		Mount[\"id\"] = 119699 	specColor = color.red\n	elseif 	( specFrost ) then		Mount[\"id\"] = 119707 	specColor = color.blue\n	else 							Mount[\"id\"] = 119708 	specColor = color.green\n	end\nend\n\n----------------------------------------------------------------------------------\n\nfunction footstepShake( cameraDummy, cameraFX )\n\n	local footstepTime = 0.4\n	local footstepAmplitude = 1\n	local cameraShake\n	\n	for i=1, 6 do	\n		cameraShake = scene:AddCameraEffect( cameraFX, cameraDummy:GetPosition(), cameraDummy, footstepAmplitude ) \n		if (Shot == 100) then break end		\n		Wait( footstepTime )\n		if (Shot == 100) then break end		\n		scene:RemoveCameraEffect(cameraShake)\n		if (Shot == 100) then break end		\n		Wait( footstepTime )\n		if (Shot == 100) then break end		\n	end\n	\n	scene:RemoveCameraEffect(cameraShake)\n	SendTrigger(\"footstepShakeEnded\")\nend\n\n----------------------------------------------------------------------------------\n\nScenePersist = true\nSendTrigger(\"FunctionsLoaded\")', 37474),
(25681, '9.0.1_[BRC]_Documentation_IGC', '--[[ \n\n	--= WORLDPORT =--\n		worldport 2453, 2690.92, 2099.32, 318.062, 3.00435\n\n	--= CONSOLE CHEAT =--\n		torghaststart\n		TorghastRunecarver \n		startquest 60272 and clearquest 60272 \n\n\n	--= TO VIEW IN GAME =--\n		1. Create a L60 character\n		1. use torghaststart to enter the scenario\n		2. startquest 60272\n		3. use TorghastRunecarver to teleport to the proper location\n		4. speak to the Runecarver\n\n\n	--= CONTACT =--\n		- Quest Designer: 	Scott Smith\n		- Producer: 		Gayeong Yoo\n		- IGC Designer: 	Robin Khamsi\n		- Sound: 			Jay Maguire\n\n--]] ', 37474),
(15714, '[1] 7.2 OHM Class Mount - DK - IGC - Offsets', 'raceHeight = (base + 0.05)\n	elseif	(worgen_m) 		then	raceScale = 0.7		raceHeight = (base + 1.2)		\n	elseif	(worgen_f) 		then	raceScale = 1		raceHeight = (base + 0.5)		\n	elseif	(raceKultiran)  then	raceScale = 1.1		raceHeight = (base + 0.1)\n	elseif	(pandaren_m)  	then	raceScale = 0.8		raceHeight = (base + 1)\n	elseif	(pandaren_f) 	then	raceScale = 1.4		raceHeight = (base + 0.06)\n	\n	elseif 	(orc_m) 		then	raceScale = 0.8		raceHeight = (base + 1.1)\n	elseif 	(orc_f) 		then	raceScale = 1.4		raceHeight = (base + 0)\n	elseif 	(undead) 		then	raceScale = 1.6		raceHeight = (base + 0)\n	elseif 	(tauren_m) 		then	raceScale = 0.5		raceHeight = (base + 1.4)\n	elseif 	(tauren_f) 		then	raceScale = 0.8		raceHeight = (base + 0.7)\n	elseif 	(troll_m) 		then	raceScale = 1.0		raceHeight = (base + 0.6)\n	elseif 	(troll_f) 		then	raceScale = 1.2		raceHeight = (base + 0)\n	elseif 	(bloodelf) 		then	raceScale = 1.5		raceHeight = (base + -0.05)\n	elseif 	(goblin) 		then	raceScale = 1.4		raceHeight = (base + 1.05)	\n	elseif	(raceZandalari) then	raceScale = 0.8		raceHeight = (base + 0.7)\n	\n	else	print(\"Invalid race\")\n	end	\nend\n\n--------------------------------------------------------------------------\n\nScenePersist = true', 37474),
(15219, '7.2 OHM Class Mount - DK - IGC - Actor IDs', 'WaitForTrigger(\"SetupLoaded\") \n \nactorTable = {}\nactorAnimTable = {}\n\n-------------------------------------------------------------------------------------------\n-- Actors\n\nPlayer = {\n	id = 95941;\n	trans = Transform:New( Vector:New( 3103.95, -203.309, 100.001 ), 71 , 0.0, 0.0 );\n	scale = 1;\n}\n\nMount = {\n	id = 119708;\n	trans = Transform:New( Vector:New( 3147.2, -206.952, 100.001 ), 115 , 0.0, 0.0 );\n	scale = 1.15;\n}\n\n\n-- Boolean flags\nhuman = 			scene:EvalPlayerCondition( 47454 )	\ndwarf = 			scene:EvalPlayerCondition( 34465 )\nnightelf = 			scene:EvalPlayerCondition( 89078 ) -- Also nightborne\ngnome = 			scene:EvalPlayerCondition( 77359 ) -- Also mechagnome\ndraenei_m = 		scene:EvalPlayerCondition( 35007 ) \ndraenei_f = 		scene:EvalPlayerCondition( 35008 ) \nworgen_m =			scene:EvalPlayerCondition( 35009 )  \nworgen_f =		 	scene:EvalPlayerCondition( 35010 )  \nraceKultiran = 		scene:EvalPlayerCondition( 66693 )\npandaren_f = 		scene:EvalPlayerCondition( 35782 )\npandaren_m = 		scene:EvalPlayerCondition( 35783 )\n\n\norc_m = 	scene:EvalPlayerCondition( 35784 ) \norc_f = 	scene:EvalPlayerCondition( 35785 ) \nundead = 	scene:EvalPlayerCondition( 47453 )\ntauren_m = 	scene:EvalPlayerCondition( 64341 ) --also highmountain\ntauren_f = 	scene:EvalPlayerCondition( 64342 ) --also highmountain\ntroll_m = 	scene:EvalPlayerCondition( 35001 ) \ntroll_f = 	scene:EvalPlayerCondition( 35002 ) \nbloodelf = 	scene:EvalPlayerCondition( 89077 ) --Also Void Elf\ngoblin = 	scene:EvalPlayerCondition( 87754 ) -- Also Vulpera\nraceMaghar 			= scene:EvalPlayerCondition( 61661 )\nraceZandalari		= scene:EvalPlayerCondition( 64968 )\n\n-------------------------------------------------------------------------------------------\n-- DOODADS\n\nDummy = {\n	id = 721;\n	trans = Transform:New( Vector:New( 0, 0, 0 ), 0 , 0.0, 0.0 );\n	scale = 1;\n}\n\n-------------------------------------------------------------------------------------------\n-- FX\n\nGroundCrack = {\n	id = fid(1389432);\n	trans = Transform:New( Vector:New( 0, 0, 0 ), 0 , 0.0, 0.0 );\n	scale = 0.2;\n}\n\nIceGround = {\n	id = fid(244075);\n	trans = Transform:New( Vector:New( 0, 0, 0 ), 0 , 0.0, 0.0 );\n	scale = .1;\n}\n\nSnowTempest = {\n	id = fid(355806);\n	trans = Transform:New( Vector:New( 0, 0, 0 ), 0 , 0.0, 0.0 );\n	scale = .1;\n}\n\n\nFrostNova = {\n	id = fid(166210);\n	trans = Transform:New( Vector:New( 0, 0, 0 ), 0 , 0.0, 0.0 );\n	scale = .1;\n}\n\nSmokeSpread = {\n	id = fid(324681);\n	trans = Transform:New( Vector:New( 0, 0, 0 ), 0 , 90.0, 0.0 );\n	scale = .1;\n}\n\nRunes = {\n	id = fid(343848);\n	trans = Transform:New( Vector:New( 0, 0, 0 ), 0 , 0.0, 0.0 );\n	scale = 0.4;\n}\n\nSouls = {\n	id = fid(1355058);\n	trans = Transform:New( Vector:New( 0, 0, 0 ), 0 , 0.0, 0.0 );\n	scale = 1;\n}\n\nMountExplosion = {\n	--id = [[SPELLS\\Vertical_Plume_Explosion.M2]];\n	id = fid(410352);\n	trans = Transform:New( Vector:New( 0, 0, 0 ), 0 , 0.0, 0.0 );\n	scale = 0.5;\n}\n\nSpreadWings = {\n	id = fid(324681);	\n	trans = Transform:New( Vector:New( 0, 0, 0 ), 0 , 90, 0.0 );\n	scale = 1;\n}\n\n\n-------------------------------------------------------------------------------------------\n\nScenePersist = true\nSendTrigger(\"ActorsLoaded\")', 37474),
