(11375, '[4] Cinematic Framework - Spawning', 'true\n	createData.smoothPhase = true\n	createData.overrideReaction = ReactionType.Friendly\n\n	local actor = scene:SpawnActor( createData )\n	return actor\n\nend\n\n--\n-- SpawnSimulatedNPCActorAtPoint( creatureID, pointsPathID, snapToGround [default 0] )\n--   Spawn an interactible and selectable actor who will smooth phase spawn at point\n-- You want to use this if you\'re looking for SmoothPhaseSpawnActorAtPoint\nfunction SpawnSimulatedNPCActorAtPoint( creatureID, pointsPathID, snapToGround )\n	\n\n	local createData = ActorCreateData:Default()\n	createData.creatureID =  creatureID\n	createData.groundSnap = (snapToGround ~= false)\n	createData.smoothPhase = true\n	createData.interactible = true\n	createData.selectable = true\n	createData.overrideReaction = ReactionType.Friendly\n	local actors = scene:SpawnActorsAtPoints( createData, pointsPathID )\n	return actors[1]\n\nend\n\n--\n-- SpawnSimulatedNPCActorsAtPoints( creatureID, pointsPathID, snapToGround [default 0] )\n--   Spawn an interactible and selectable actors who will smooth phase spawn at points\n--\nfunction SpawnSimulatedNPCActorsAtPoints( creatureID, pointsPathID, snapToGround )\n	\n\n	local createData = ActorCreateData:Default()\n	createData.creatureID =  creatureID\n	createData.groundSnap = (snapToGround ~= false)\n	createData.smoothPhase = true\n	createData.interactible = true\n	createData.selectable = true\n	createData.overrideReaction = ReactionType.Friendly\n	local actors = scene:SpawnActorsAtPoints( createData, pointsPathID )\n	return actors\n\nend\n\n--\n-- SpawnWMOActorAtPoint( wmoDisplayID, pointsPathID, scale [default 1], offsetFacing [default 0], snapToGround [default false])\n-- Spawn a WMO at a specified Point. wmoDisplayID can be found in WOWEdit under GameObjectDisplayInfo\n---\nfunction SpawnWMOActorAtPoint( wmoDisplayID, pointsPathID, scale, offsetFacing, snapToGround )\n\n	local createData = ActorCreateData:Default()\n	createData.wmoGameObjectDisplayID = wmoDisplayID\n	createData.scale = scale or 1\n	createData.facingOffset = offsetFacing or 0\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = false\n	\n	local actors = scene:SpawnActorsAtPoints( createData, pointsPathID )\n	return actors[1]\n	\nend\n\n--\n-- SpawnWMOActor( wmoDisplayID, x, y, z, facing, scale, offsetFacing, snapToGround )\n-- Spawn a WMO at a coordinate. wmoDisplayID can be found in WOWEdit under GameObjectDisplayInfo\n---\nfunction SpawnWMOActor( wmoDisplayID, x, y, z, facing, scale, offsetFacing, snapToGround )\n\n	local spawnPos = Vector:New( x, y, z )\n	local spawnTransform = Transform:New( spawnPos, facing )\n	local createData = ActorCreateData:Default()\n	createData.wmoGameObjectDisplayID = wmoDisplayID\n	createData.transform = spawnTransform\n	createData.facing = facing or 0\n	createData.scale = scale or 1\n	createData.facingOffset = offsetFacing or 0\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = false\n\n	local actor = scene:SpawnActor( createData )\n	return actor\n	\nend', 37474),
(1665, '[2] Cinematic Framework - Spawning', 'then\n		clonesAvailable = false\n		creatureID = 65247 -- backup clone creature\n	end\n\n	local createData = ActorCreateData:New( creatureID, spawnTransform, scale )\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = false\n	createData.smoothPhase = true\n\n	local actor = nil\n	if (clonesAvailable == true ) then\n		actor = scene:SpawnActivePlayerCloneActor( createData, false )\n	end\n\n	if (not actor) then\n		actor = scene:SpawnActor( createData )\n	end\n\n	actor:SetInteractible( false )\n	WaitForSmoothPhase( createData )\n\n	return actor\n\nend\n\n\n--\n-- SpawnModelActor( modelFileName, x, y, z, facing [default 0], scale [default 1] )\n--   Spawn an uninteractible actor\n--\nfunction SpawnModelActor( modelFileName, x, y, z, facing, scale, snapToGround )\n	if not facing then\n		facing = 0\n	end\n\n	if not scale then\n		scale = 1\n	end\n\n	local pos = Vector:New( x, y, z )\n	local transform = Transform:New( pos, facing )\n	local createData = ActorCreateData:NewModel( \"dummy\", modelFileName, transform, scale )\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = false\n\n	local actor = scene:SpawnActor( createData )\n	return actor\n\nend\n\n--\n-- SpawnInteractibleActor( creatureID, x, y, z, facing [default 0], scale [default 1] )\n--   Spawn an Interactible actor\n--\nfunction SpawnInteractibleActor( creatureID, x, y, z, facing, scale, snapToGround )\n	if not facing then\n		facing = 0\n	end\n\n	if not scale then\n		scale = 1\n	end\n\n	local spawnPos = Vector:New( x, y, z )\n	local spawnTransform = Transform:New( spawnPos, facing )\n	local createData = ActorCreateData:New( creatureID, spawnTransform, scale )\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = true\n\n	local actor = scene:SpawnActor( createData )\n	return actor\n\nend\n\n-- SmoothPhaseSpawnInteractibleActor( creatureID, x, y, z, facing [default 0], scale [default 1] )\n--   Spawn an Interactible actor\n--\nfunction SmoothPhaseSpawnInteractibleActor( creatureID, x, y, z, facing, scale, snapToGround )\n	if not facing then\n		facing = 0\n	end\n\n	if not scale then\n		scale = 1\n	end\n\n	local spawnPos = Vector:New( x, y, z )\n	local spawnTransform = Transform:New( spawnPos, facing )\n	local createData = ActorCreateData:New( creatureID, spawnTransform, scale )\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = true\n	createData.smoothPhase = true\n\n	WaitForSmoothPhase(createData)\n\n	local actor = scene:SpawnActor( createData )\n	return actor\nend\n\n--\n-- SpawnModelActor( modelFileName, pointsPathID, snapToGround [=true] )\n--   Spawn multiple uninteractable actors at points using an .M2 model\n--\nfunction SpawnModelActorsAtPoints( modelFileName, pointsPathID, snapToGround, scale )\n\n	if not scale then\n		scale = 1\n	end\n\n	local createData = ActorCreateData:Default()\n	if type(modelFileName) == \"number\" then\n		createData.modelFileID = modelFileName\n	else\n		createData.model = modelFileName\n	end\n	createData.scale = scale\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = false\n\n	local actors = scene:SpawnActorsAtPoints( createData, pointsPathID )\n	return actors\n\nend\n\n--\n-- SpawnModelActorAtPoint( modelFileName, pointsPathID, snapToGround [=true], scale [default 1] )\n--   Spawn single uninteractable actor at point using an .M2 model\n--\nfunction SpawnModelActorAtPoint( modelFileName, pointsPathID, snapToGround, scale )\n\n	if not scale then\n		scale = 1\n	end\n\n	local createData = ActorCreateData:Default()\n	if type(modelFileName) == \"number\" then\n		createData.modelFileID = modelFileName\n	else\n		createData.model = modelFileName\n	end\n	createData.scale = scale\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = false\n\n	local actors = scene:SpawnActorsAtPoints( createData, pointsPathID )\n	', 37474),
(25033, '9.0 Maldraxxus - Mainline - Rune Unlock - Init - SJC', 'scene:SetRelativeCoords(true)\n\n--Quick check for Rune Visuals\n\n--SPELLVISUALID   = INTEGER - ID of the spell visual for the rune\n\n\n--Second Rune (Template)\n	if scene:EvalPlayerCondition(80538) then\n		SPELLVISUALID = 98043\n--Third Rune (Template)\n	elseif scene:EvalPlayerCondition(80565) then\n		SPELLVISUALID = 98047\n--Fourth Rune\n	elseif scene:EvalPlayerCondition(80571) then\n		SPELLVISUALID = 98052\n--Final Rune\n--	elseif scene:EvalPlayerCondition(80571) then\n--		SPELLVISUALID = 98053\n--First Rune\n	else\n		SPELLVISUALID = 98006\n	end\n\n--scene:SetFadeRegionExcludesAllNonPlayers(true)\n\n\n--Player Clone\n---- SpawnActivePlayerCloneActor( x, y, z, facing [default 0], scale [default 1], snapToGround)\n\nscene:SetFadeRegion(100, true) -- (radius, fadeActivePlayer)\nscene:SetFadeRegionExcludesAllNonPlayers(false)\n\nclone = SpawnActivePlayerCloneActor( 0, 0, 0, 0, 1, true, true)\n--clone = SmoothPhaseSpawnActivePlayerCloneActor(0, 0, 0, 0, 1, true )\n\n\n--Equip Clone with Runeblade\n\nclone:EquipWeapon(WeaponSlot.MainHand, 178905)\n\nSendTrigger(\"Smooth Phase Complete\")', 37474),
(11151, '[3] Cinematic Framework - Spawning', 'return actors[1]\n\nend\n\n\nfunction SpawnActorAtPoint( creatureID, pointsPathID, snapToGround, scale )\n\n	if not scale then\n		scale = 1\n	end\n\n	local createData = ActorCreateData:Default()\n	createData.creatureID =  creatureID\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = false\n\n	local actors = scene:SpawnActorsAtPoints( createData, pointsPathID )\n	return actors[1]\n\nend\n\nfunction SpawnFadedActorAtPoint( creatureID, pointsPathID, snapToGround )\n\n	local createData = ActorCreateData:Default()\n	createData.creatureID =  creatureID\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = false\n\n	local actors = scene:SpawnActorsAtPoints( createData, pointsPathID )\n	local actor = actors[1]\n	FadeOut(actor, 0)\n	return actor\n\nend\n\nfunction SpawnActorsAtPoints( creatureID, pointsPathID, snapToGround )\n\n	local createData = ActorCreateData:Default()\n	createData.creatureID =  creatureID\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = false\n\n	local actors = scene:SpawnActorsAtPoints( createData, pointsPathID )\n	return actors\n\nend\n\nfunction SpawnFadedActorsAtPoints( creatureID, pointsPathID, snapToGround )\n\n	local createData = ActorCreateData:Default()\n	createData.creatureID =  creatureID\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = false\n\n	local actors = scene:SpawnActorsAtPoints( createData, pointsPathID )\n	for i = 1, (#actors) do\n		FadeOut(actors[i], 0)\n	end\n	\n	return actors\n\nend\n\nfunction SpawnPlayerCloneAtPoint( pathID, scale, snapToGround, useNativeVisual )\n	local path = scene:LoadPath( pathID )\n	local pos = path.nodes[1].pos\n	local x = pos.x\n	local y = pos.y\n	local z = pos.z\n	local facing = pos.facing\n	\n	local player = SpawnActivePlayerCloneActor( x, y, z, facing, scale, snapToGround, useNativeVisual )\n	return player\nend\n\n--\n-- SmoothPhaseSpawnActorsAtPoints( creatureID, pointsPathID, snapToGround [=true] )\n--     This is for smooth phasing in a number of actors at points. These must have the same display ID to work.\n--\nfunction SmoothPhaseSpawnActorsAtPoints( creatureID, pointsPathID, snapToGround )\n\n	local createData = ActorCreateData:Default()\n	createData.creatureID =  creatureID\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = false\n	createData.smoothPhase = true\n\n	local actors = scene:SpawnActorsAtPoints( createData, pointsPathID )\n	return actors\n\nend\n\n--\n-- SpawnSelectableActor( creatureID, x, y, z, facing [default 0], scale [default 1] )\n--   Spawn an interactible and selectable actor\n--\nfunction SpawnSelectableActor( creatureID, x, y, z, facing, scale, snapToGround )\n	if not facing then\n		facing = 0\n	end\n\n	if not scale then\n		scale = 1\n	end\n\n	local spawnPos = Vector:New( x, y, z )\n	local spawnTransform = Transform:New( spawnPos, facing )\n	local createData = ActorCreateData:New( creatureID, spawnTransform, scale )\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = true\n	createData.selectable = true\n	createData.overrideReaction = ReactionType.Friendly\n\n	local actor = scene:SpawnActor( createData )\n	--actor:SetInteractible( false )\n	return actor\n\nend\n\n--\n-- SpawnSimulatedNPCActor( creatureID, x, y, z, facing [default 0], scale [default 1] )\n--   Spawn an interactible and selectable actor at x, y, z, and facing.\n--\nfunction SpawnSimulatedNPCActor( creatureID, x, y, z, facing, scale, snapToGround )\n	if not facing then\n		facing = 0\n	end\n\n	if not scale then\n		scale = 1\n	end\n\n	local spawnPos = Vector:New( x, y, z )\n	local spawnTransform = Transform:New( spawnPos, facing )\n	local createData = ActorCreateData:New( creatureID, spawnTransform, scale )\n	createData.groundSnap = (snapToGround ~= false)\n	createData.interactible = true\n	createData.selectable = ', 37474),
(24406, '9.0 Maw - Oribos to the Maw - Skyjump (RKS)', '\n\n-------------------\n-- Configuration --\n-------------------\n\nscene:SetRelativeCoords(true)\nscene:SetFadeRegion(3, true)\n\n\n----------\n-- Init --\n----------\n\n--Variables\ncameraID = 522\njumpAnimKitID = 21322\nendAnimKitID = 19766\njumpTime = 4\ncameraResetTime = 1.5\nresetTime = 0.87\njumpHeight = 120\nstartCameraDepth = 80\n\njumpStartPoint = Vector:New(0,0,jumpHeight)\n\n--Bunnies\nbunnyCreatureID = 62026\ncameraBunny = SpawnActor( bunnyCreatureID, -20, -23, jumpHeight-startCameraDepth, 0, 1, false)\nimpactBunny = SpawnActor( bunnyCreatureID, 0, 0, 0, 0, 1, false)\n\n--SpellAuraVisuals\ntrailAuraVisualID = 100938\n\n--Spells\nbigImpact = 319738\n\n-- Set camera to look at where the clone will appear from as soon as possible\nscene:WaitTimer(0) \n\n--Player Actor\nplayerActor = SpawnActivePlayerCloneActor( jumpStartPoint.x, jumpStartPoint.y, jumpStartPoint.z, 0, 1, false, true )\nwhile not playerActor:IsReadyToDisplay() do\n	scene:WaitTimer(0)\nend\n\n--Move camera back slowly\nRideVehicleActor(cameraBunny, playerActor, 2, AttachmentPoint.Base, Vector:New(23,-20,10), Vector:New(0,0,0), Animations.None)\n\n--------------\n-- Movement --\n--------------\n-- Custom built jump \nlocal crashData = MoveData:Default(2)\ncrashData.time = jumpTime\ncrashData.posControl = MovePosControl.TotalTime\ncrashData.yawControl = MoveRotControl.Angle\ncrashData.pitchControl = MoveRotControl.Angle\ncrashData.rollControl = MoveRotControl.Angle\ncrashData.isRelative = false -- true\ncrashData.teleportToFirstPoint = true -- false\ncrashData.isGroundSnapping = false\ncrashData.animKitID = jumpAnimKitID\n\n-- Offsets from origin\ncrashData.points[1].pos = jumpStartPoint\ncrashData.points[2].pos = Vector:New(0,0,0)\n\n-- Set fancy pitch angle\n--crashData.points[1].pitch = 210\n--crashData.points[2].pitch = 210\n\n\n-------------------\n-- OnScene Start --\n-------------------\n-- wait a fraction of a second to cover loading. If more loading needs to be done,\n-- the scene will pause longer before initiating the move. For this reason, the controlling\n-- aura is set a little longer than the scene\n\nscene:SetCamera( cameraID, 0, cameraBunny, playerActor )\n\nSendTrigger(\"remove\")\n\n-- Make player clone drop from the sky\nplayerActor:Move(crashData)\n\nlocal trailAura1 = playerActor:PlaySpellStateVisual(trailAuraVisualID) \n\n\n-- Wait until landing\nscene:WaitTimer(jumpTime-cameraResetTime)\n\n--Move camera near final position\n--RideVehicleActor(cameraBunny, playerActor, cameraResetTime, AttachmentPoint.Base, Vector:New(20,0,-15), Vector:New(0,0,0), Animations.None)\nJumpExitVehicleActor(cameraBunny, Vector:New(-20,0,15), cameraResetTime)\nWait(cameraResetTime)\nscene:SetCamera(0,resetTime,nil,nil) -- Set camera back to game-cam\n\n--Camera Dismounts player\n\n--Impact\nCastSpellAtActor(impactBunny, impactBunny, bigImpact)\n\n\n-- Bring the player back\nscene:SetFadeRegion(0, false)\nplayerActor:ClearSpellVisual(trailAura1)\nFadeOut(playerActor, 0)\n--playerActor:Despawn()\n\n--local playerDisplay = scene:GetActivePlayerDisplay()\n--playerDisplay:PlayAnimKit(endAnimKitID, true, Animations.None)\nWait(resetTime)\n\nscene:EndScene()', 37474),
(26004, '9.0 Oribos - Jump Into Maw - Camera - PRK', 'local genericFOV90 = 368\nlocal genericFOV60 = 369\nlocal genericFOV45 = 370\nlocal genericFOV30 = 371\n\nlocal player = scene:GetActivePlayerDisplay()\nlocal playerPos = player:GetPosition()\nlocal cameraZUp = 5\nlocal scenePos = scene:GetPosition()\nlocal totalTime = 5\n\n--Play trail\nlocal trailAuraVisualID = 94856\nlocal trailAura1 = player:PlaySpellStateVisual(trailAuraVisualID) \n\n--Create camera\nlocal cameraDummyDefaultPos = scene:GetPosition()\nlocal cameraDummyModel = fid(124640)\n\nlocal cameraDummyCreateData = ActorCreateData:Default()\ncameraDummyCreateData.modelFileID = cameraDummyModel\ncameraDummyCreateData.transform.position = cameraDummyDefaultPos\ncameraDummyCreateData.groundSnap = false\ncameraDummyCreateData.interactible = false\ncameraDummyCreateData.floatingTooltip = false\ncamera = scene:SpawnActor(cameraDummyCreateData)\ncameraTgt = scene:SpawnActor(cameraDummyCreateData)\nRideVehicleActor(cameraTgt, player, 0, AttachmentPoint.Base, Vector:New(0, 0, -8), Vector:New(0,0,0))\n\n--Move camera\nscene:SetCamera( genericFOV90, 2, camera, cameraTgt)\n\ncamera:MoveToAbs(Vector:New(playerPos.x, playerPos.y, playerPos.z + cameraZUp), 3)\n\nWait(totalTime)\n\nscene:EndScene()\n', 37474),
